        </div>
        {user && (
          <button
            onClick={() => setShowUpload(true)}
            className="flex items-center gap-1.5 bg-[#25D366] text-white px-3 py-1.5 rounded-full text-sm font-semibold hover:bg-[#1da055] transition"
