        <button className="flex-shrink-0 bg-white text-[#075E54] text-xs font-bold px-3 py-1.5 rounded-xl hover:bg-green-50 transition whitespace-nowrap">
          {ad.cta_text || 'View'}
        </button>
      </div>
    </motion.div>
  );
}

